107	func ParseRegistryURL(registryURL string) (*URLInfo, error) {
108		parsedURL, err := url.Parse(registryURL)
109		if err != nil {
110			return nil, fmt.Errorf("invalid registry URL: %w", err)
111		}
112	
113		if parsedURL.Scheme != RegistryURLScheme {
114			return nil, fmt.Errorf("invalid registry URL scheme: expected %s, got %s", RegistryURLScheme, parsedURL.Scheme)
115		}
116	
117		resourceType := parsedURL.Host
118		if resourceType == "" {
119			return nil, errors.New("invalid registry URL: missing resource type")
120		}
121	
122		urlPath := strings.TrimPrefix(parsedURL.Path, "/")
123		parts := strings.Split(urlPath, "/")
124		if len(parts) != 3 {
125			return nil, &InvalidRegistryURLError{
126				URL:    registryURL,
127				Reason: fmt.Sprintf("expected format: registry://%s/source/publisher/name[@version]", resourceType),
128			}
129		}
130	
131		source := parts[0]
132		if source == "" {
133			return nil, &InvalidRegistryURLError{
134				URL:    registryURL,
135				Reason: "missing source",
136			}
137		}
138	
139		publisher := parts[1]
140		if publisher == "" {
141			return nil, &InvalidRegistryURLError{
142				URL:    registryURL,
143				Reason: "missing publisher",
144			}
145		}
146	
147		nameAndVersion := parts[2]
148		nameVersionParts := strings.Split(nameAndVersion, "@")
149		if len(nameVersionParts) > 2 {
150			return nil, &InvalidRegistryURLError{
151				URL:    registryURL,
152				Reason: fmt.Sprintf("expected format: registry://%s/source/publisher/name[@version]", resourceType),
153			}
154		}
155	
156		encodedName := nameVersionParts[0]
157		if encodedName == "" {
158			return nil, &InvalidRegistryURLError{
159				URL:    registryURL,
160				Reason: "missing name",
161			}
162		}
163	
164		name, err := decodeArtifactNamePart(encodedName)
165		if err != nil {
166			return nil, &InvalidRegistryURLError{
167				URL:    registryURL,
168				Reason: fmt.Sprintf("failed to decode name: %v", err),
169			}
170		}
171	
172		var version *semver.Version
173		if len(nameVersionParts) == 2 {
174			versionStr := nameVersionParts[1]
175			if versionStr == "" {
176				return nil, &InvalidRegistryURLError{
177					URL:    registryURL,
178					Reason: "missing version",
179				}
180			}
181	
182			if versionStr != "latest" {
183				version, err = parseVersion(versionStr)
184				if err != nil {
185					return nil, &InvalidRegistryURLError{
186						URL:    registryURL,
187						Reason: fmt.Sprintf("invalid version %q: %v", versionStr, err),
188					}
189				}
190			}
191		}
192	
193		return &URLInfo{
194			resourceType: resourceType,
195			source:       source,
196			publisher:    publisher,
197			name:         name,
198			version:      version,
199		}, nil
200	}
